use arc_swap::ArcSwap;
static RULES: Lazy<ArcSwap<RoutingTable>> =
    Lazy::new(|| ArcSwap::from_pointee(RoutingTable::default()));

fn route(msg: &Message) -> Outcome {
    let table = RULES.load();                 // one consistent snapshot
    match table.dest_for(msg.kind()) {
        Some(dest) => dest.send(msg),          // guard alive: table not freed
        None => dead_letter(msg),
    }
}
fn publish(next: RoutingTable) { RULES.store(Arc::new(next)); }
